// Local repro harness mimicking fuzz/assimp_fuzzer.cc
#include <assimp/cimport.h>
#include <assimp/Importer.hpp>
#include <assimp/scene.h>
#include <assimp/postprocess.h>

#include <cstdio>
#include <cstdlib>
#include <vector>

using namespace Assimp;

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <input-file>\n", argv[0]);
        return 2;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "cannot open %s\n", argv[1]);
        return 2;
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<uint8_t> data(len);
    if (len > 0 && fread(data.data(), 1, len, f) != (size_t)len) {
        fprintf(stderr, "read error\n");
        return 2;
    }
    fclose(f);

    Importer importer;
    unsigned int flags = aiProcessPreset_TargetRealtime_Quality | aiProcess_ValidateDataStructure;
    const aiScene *sc = importer.ReadFileFromMemory(data.data(), data.size(), flags, nullptr);
    if (sc == nullptr) {
        fprintf(stderr, "import failed: %s\n", importer.GetErrorString());
        return 1;
    }
    fprintf(stderr, "import ok: %u meshes\n", sc->mNumMeshes);
    return 0;
}

