#include <assimp/Importer.hpp>
#include <assimp/scene.h>
#include <assimp/postprocess.h>
#include <cstdio>
#include <cstdlib>
#include <vector>

using namespace Assimp;

static void dumpScene(const char *tag, const aiScene *sc) {
    fprintf(stderr, "--- %s: %u meshes\n", tag, sc->mNumMeshes);
    for (unsigned int i = 0; i < sc->mNumMeshes; ++i) {
        const aiMesh *m = sc->mMeshes[i];
        fprintf(stderr, "  mesh[%u] verts=%u faces=%u primTypes=0x%x name=%s\n",
                i, m->mNumVertices, m->mNumFaces, m->mPrimitiveTypes, m->mName.C_Str());
        if (m->mNumFaces > 0 && m->mFaces) {
            fprintf(stderr, "    face0: numIndices=%u\n", m->mFaces[0].mNumIndices);
        }
    }
}

int main(int argc, char **argv) {
    if (argc < 3) return 2;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 2;
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<uint8_t> data(len);
    if (len > 0 && fread(data.data(), 1, len, f) != (size_t)len) return 2;
    fclose(f);

    unsigned int flags = (unsigned int)strtoul(argv[2], nullptr, 0);
    Importer importer;
    const aiScene *sc = importer.ReadFileFromMemory(data.data(), data.size(), flags, nullptr);
    if (sc == nullptr) {
        fprintf(stderr, "import failed: %s\n", importer.GetErrorString());
        return 1;
    }
    dumpScene("result", sc);
    return 0;
}

