// Minimal driver that mimics libFuzzer's single-input mode:
// assimp_fuzzer <file>  -> run LLVMFuzzerTestOneInput on file contents.
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <vector>

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <input-file>\n", argv[0]);
        return 0;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "cannot open %s\n", argv[1]);
        return 0;
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<uint8_t> data(len > 0 ? len : 1);
    if (len > 0 && fread(data.data(), 1, len, f) != (size_t)len) {
        fclose(f);
        return 0;
    }
    fclose(f);
    return LLVMFuzzerTestOneInput(data.data(), (size_t)len);
}
